// Tests of the zone-file parser.
//
// WHY THEY EXIST: the `records` checks compare the public DNS with the record
// set the mail server says it expects. That expectation comes from a zone file
// generated by an external program, and no sample of it lives in this repository
// — so the parser is written against what BIND accepts, and these tests are the
// only statement of what "BIND accepts" means here. Each test names one syntax
// the file is known to use, so a regression points at the exact form that broke.
package mail

import (
	"testing"
)

func recordsParNom(records []enregistrementZone, nom, genre string) []enregistrementZone {
	trouves := make([]enregistrementZone, 0, 1)
	for _, r := range records {
		if r.Nom == nom && r.Type == genre {
			trouves = append(trouves, r)
		}
	}
	return trouves
}

func TestLireZoneOrigineEtRelatifs(t *testing.T) {
	zone := `$ORIGIN sub.ceffio.org.
$TTL 3600
@                 IN A 203.0.113.10
www               IN A 203.0.113.11
max.ceffio.org.   IN A 203.0.113.12
`
	records := lireZone(zone, "ceffio.org")
	if len(records) != 3 {
		t.Fatalf("got %d records, want 3: %+v", len(records), records)
	}

	// `@` is the current origin, here the $ORIGIN line, not the domain.
	arobase := recordsParNom(records, "sub.ceffio.org", "A")
	if len(arobase) != 1 || arobase[0].Champs[0] != "203.0.113.10" {
		t.Fatalf("@ did not resolve to the $ORIGIN: %+v", arobase)
	}
	// A relative owner is appended to the origin...
	if len(recordsParNom(records, "www.sub.ceffio.org", "A")) != 1 {
		t.Fatalf("www was not made relative to the $ORIGIN: %+v", records)
	}
	// ...while an absolute owner is left alone, with or without its trailing dot.
	if len(recordsParNom(records, "max.ceffio.org", "A")) != 1 {
		t.Fatalf("the absolute owner was not kept as written: %+v", records)
	}

	// The same two spellings of one absolute name must land on the same name when
	// the origin is the domain itself.
	autre := lireZone("$ORIGIN ceffio.org.\nmail IN A 203.0.113.12\nmail.ceffio.org IN A 203.0.113.13\n", "ceffio.org")
	if len(autre) != 2 || autre[0].Nom != "mail.ceffio.org" || autre[1].Nom != "mail.ceffio.org" {
		t.Fatalf("the two spellings of the same owner were not merged: %+v", autre)
	}
}

func TestLireZoneSansProprietaire(t *testing.T) {
	zone := "$ORIGIN ceffio.org.\n" +
		"@  IN MX 10 mail.ceffio.org.\n" +
		"   IN TXT \"v=spf1 mx -all\"\n"
	records := lireZone(zone, "ceffio.org")
	if len(records) != 2 {
		t.Fatalf("got %d records, want 2: %+v", len(records), records)
	}
	// A line starting with white space belongs to the previous owner: that is how
	// a zone file groups the records of one name.
	if records[1].Nom != "ceffio.org" || records[1].Type != "TXT" {
		t.Fatalf("the blank owner did not continue the previous name: %+v", records[1])
	}
	if records[1].Valeur() != "v=spf1 mx -all" {
		t.Fatalf("the TXT content was not decoded: %q", records[1].Valeur())
	}
}

func TestLireZoneTXTMultiChunks(t *testing.T) {
	zone := `$ORIGIN ceffio.org.
ceffio._domainkey IN TXT "v=DKIM1; k=rsa; " "p=MIIBIjANBgkq" "hAgEAAQ"
`
	records := lireZone(zone, "ceffio.org")
	if len(records) != 1 {
		t.Fatalf("got %d records, want 1: %+v", len(records), records)
	}
	enr := records[0]
	if enr.Nom != "ceffio._domainkey.ceffio.org" {
		t.Fatalf("nom = %q", enr.Nom)
	}
	if len(enr.Champs) != 3 {
		t.Fatalf("got %d character-strings, want 3: %+v", len(enr.Champs), enr.Champs)
	}
	// A resolver concatenates the character-strings of one record, so the
	// expected value must be their concatenation — and the Fix must keep them
	// apart, because one long string would be split again by the server.
	if enr.Valeur() != "v=DKIM1; k=rsa; p=MIIBIjANBgkqhAgEAAQ" {
		t.Fatalf("Valeur() = %q", enr.Valeur())
	}
	ligne := enr.ligneZone()
	if ligne != `ceffio._domainkey.ceffio.org. IN TXT "v=DKIM1; k=rsa; " "p=MIIBIjANBgkq" "hAgEAAQ"` {
		t.Fatalf("ligneZone() = %q", ligne)
	}
}

func TestLireZoneParenthesesEtCommentaires(t *testing.T) {
	zone := `$ORIGIN ceffio.org.
@ IN SOA ns1.ceffio.org. admin.ceffio.org. (
        2026010101 ; serial
        3600       ; refresh
        600        ; retry
        604800     ; expire
        300 )      ; minimum
@ IN TXT "un ; point-virgule cité" ; un vrai commentaire
`
	records := lireZone(zone, "ceffio.org")
	if len(records) != 2 {
		t.Fatalf("got %d records, want 2: %+v", len(records), records)
	}
	soa := records[0]
	if soa.Type != "SOA" {
		t.Fatalf("the multiline record was not assembled: %+v", soa)
	}
	if len(soa.Champs) != 7 {
		t.Fatalf("got %d SOA fields, want 7: %+v", len(soa.Champs), soa.Champs)
	}
	if soa.Champs[0] != "ns1.ceffio.org." || soa.Champs[6] != "300" {
		t.Fatalf("the SOA fields were not decoded: %+v", soa.Champs)
	}
	// A `;` inside quotes is data, not a comment; the one outside is dropped.
	txt := records[1]
	if txt.Valeur() != "un ; point-virgule cité" {
		t.Fatalf("the quoted semicolon was taken for a comment: %q", txt.Valeur())
	}
}

func TestLireZoneTTLEtClasse(t *testing.T) {
	zone := `$ORIGIN ceffio.org.
mail 3600 IN A 203.0.113.10
mail 1h IN A 203.0.113.11
mail IN 2d A 203.0.113.12
`
	records := lireZone(zone, "ceffio.org")
	if len(records) != 3 {
		t.Fatalf("got %d records, want 3: %+v", len(records), records)
	}
	for i, attendu := range []string{"203.0.113.10", "203.0.113.11", "203.0.113.12"} {
		if records[i].Champs[0] != attendu {
			t.Fatalf("record %d: Champs = %+v, want %s", i, records[i].Champs, attendu)
		}
	}
}

func TestLireZoneLignesIgnorees(t *testing.T) {
	zone := `$ORIGIN ceffio.org.
$TTL 3600
ceci n'est pas une ligne de zone
mail IN A 203.0.113.10
mail IN TYPE65534 \# 4 01020304
`
	records := lireZone(zone, "ceffio.org")
	if len(records) != 1 {
		t.Fatalf("got %d records, want 1: %+v", len(records), records)
	}
	// External input: a line the parser does not understand is skipped, never
	// turned into a record with a guessed type.
	if records[0].Type != "A" {
		t.Fatalf("record type = %q, want A", records[0].Type)
	}
}

func TestLireZoneCasse(t *testing.T) {
	zone := "$ORIGIN CEFFIO.ORG.\nMaIl In A 203.0.113.10\n"
	records := lireZone(zone, "ceffio.org")
	if len(records) != 1 {
		t.Fatalf("got %d records, want 1: %+v", len(records), records)
	}
	// Names are compared case-insensitively, so they are stored in one case.
	if records[0].Nom != "mail.ceffio.org" || records[0].Type != "A" {
		t.Fatalf("nom = %q, type = %q", records[0].Nom, records[0].Type)
	}
}

func TestLigneZoneCNAME(t *testing.T) {
	enr := enregistrementZone{Nom: "mta-sts.ceffio.org", Type: "CNAME", Champs: []string{"mail.ceffio.org."}}
	if got := enr.ligneZone(); got != "mta-sts.ceffio.org. IN CNAME mail.ceffio.org." {
		t.Fatalf("ligneZone() = %q", got)
	}
}

func TestEstTTL(t *testing.T) {
	for _, cas := range []struct {
		jeton   string
		attendu bool
	}{
		{"3600", true},
		{"0", true},
		{"1h", true},
		{"2d", true},
		{"1W", true},
		{"", false},
		{"h", false},
		{"1x", false},
		{"1h30", false},
		{"A", false},
	} {
		if got := estTTL(cas.jeton); got != cas.attendu {
			t.Fatalf("estTTL(%q) = %v, want %v", cas.jeton, got, cas.attendu)
		}
	}
}

func TestAbsolutiser(t *testing.T) {
	for _, cas := range []struct {
		nom     string
		origine string
		attendu string
	}{
		{"@", "ceffio.org.", "ceffio.org."},
		{"mail", "ceffio.org.", "mail.ceffio.org."},
		{"mail.ceffio.org.", "ceffio.org.", "mail.ceffio.org."},
		{"mail.ceffio.org", "ceffio.org.", "mail.ceffio.org."},
		{"mail.autre.net.", "ceffio.org.", "mail.autre.net."},
		{"mail", "", "mail."},
	} {
		if got := absolutiser(cas.nom, cas.origine); got != cas.attendu {
			t.Fatalf("absolutiser(%q, %q) = %q, want %q", cas.nom, cas.origine, got, cas.attendu)
		}
	}
}

func TestDecouperProprietaireSRV(t *testing.T) {
	service, proto, ok := decouperProprietaireSRV("_imaps._tcp.ceffio.org", "ceffio.org")
	if !ok || service != "_imaps" || proto != "tcp" {
		t.Fatalf("got (%q, %q, %v)", service, proto, ok)
	}
	// A name that does not carry exactly service.proto under the domain is not a
	// discovery record, and the SRV family must ignore it rather than guess.
	for _, nom := range []string{"_tcp.ceffio.org", "_imaps._tcp._sub.ceffio.org", "_imaps._tcp.autre.net"} {
		if _, _, ok := decouperProprietaireSRV(nom, "ceffio.org"); ok {
			t.Fatalf("%q was taken for a discovery record", nom)
		}
	}
}

func TestZoneCompleteSeLit(t *testing.T) {
	records := lireZone(zoneComplete, "ceffio.org")
	if len(records) != 11 {
		t.Fatalf("got %d records, want 11: %+v", len(records), records)
	}
	// The two discovery records must keep their owner, target and port: a client
	// reads exactly those three.
	srv := recordsParNom(records, "_imaps._tcp.ceffio.org", "SRV")
	if len(srv) != 1 {
		t.Fatalf("the SRV record was not parsed: %+v", records)
	}
	if len(srv[0].Champs) != 4 || srv[0].Champs[3] != "mail.ceffio.org." {
		t.Fatalf("SRV fields = %+v", srv[0].Champs)
	}
	service, proto, ok := decouperProprietaireSRV(srv[0].Nom, "ceffio.org")
	if !ok || service != "_imaps" || proto != "tcp" {
		t.Fatalf("the SRV owner was not split: (%q, %q, %v)", service, proto, ok)
	}
}
